@pytest.mark.pre_alloc_mutable
def test_gas_cost_berlin(
    state_test: StateTestFiller,
    pre: Alloc,
    tx_data_hex: str,
    expected_post: dict,
) -> None:
    """Ori Pomerantz qbzzt1@gmail.com."""
    coinbase = Address("0x2adc25665018aa1fe0e6bc666dac8fc2697ff9ba")
    sender = Address("0x56724d001b4f2a2888a81971a64aad37cd43f881")
    contract = Address("0x2f170b2347023bb6bf3eec84b53259b96e0268c3")

    env = Environment(
        fee_recipient=coinbase,
        number=1,
        timestamp=1000,
        prev_randao=0x20000,
        base_fee_per_gas=10,
        gas_limit=100000000,
    )

    pre[contract] = Account(
        balance=0xBA1A9CE0BA1A9CE,
        nonce=0,
        code=bytes.fromhex(
            "60f860020a600035046102005261ffff60e860020a600035041661034052601161026052"  # noqa: E501
            "5b61026051156076576001610260510361026052606161022051610100600001015360da"  # noqa: E501
            "600161022051610100600001010153607a60026102205161010060000101015360036102"  # noqa: E501
            "205101610220526024565b61020051610220516101006000010153600060016102205161"  # noqa: E501
            "01006000010101536002610220510161022052601b806100fa6000396102405260026101"  # noqa: E501
            "000260006000f0610280525a61030052600060006000600060006102805162010000f150"  # noqa: E501
            "5a610320526103405160b961032051610300510303036000556103405160015500fe6101"  # noqa: E501
            "0061010060000161010060000139610100610100600001f300"
        ),
        storage={0x0: 0x60A7},
    )
    pre[sender] = Account(balance=0xBA1A9CE0BA1A9CE, nonce=0)

    tx_data = bytes.fromhex(tx_data_hex) if tx_data_hex else b""

    tx = Transaction(
        secret_key=Hash(
            "0x40ac0fc28c27e961ee46ec43355a094de205856edbd4654cf2577c2608d4ec1e"  # noqa: E501
        ),
        to=contract,
        data=tx_data,
        gas_limit=16777216,
        gas_price=10,
        nonce=0,
        value=1,
    )

    post = expected_post

    state_test(env=env, pre=pre, post=post, tx=tx)
